 async Task WillowArchitectureChecks(){MigrationChecks.Assert(familyHome.HasNode("WillowStairs"),"Victorian house includes a real staircase");player.Position=FamilyPoint(0,.1f,1.1f);player.Velocity=Vector3.Zero;await ToSignal(GetTree(),SceneTree.SignalName.PhysicsFrame);for(int i=0;i<230;i++){float dt=(float)GetPhysicsProcessDeltaTime();player.Velocity=new(0,player.IsOnFloor()?-.1f:player.Velocity.Y-18*dt,-3);player.MoveAndSlide();await ToSignal(GetTree(),SceneTree.SignalName.PhysicsFrame);if(player.Position.Y>familyFloor+3.35&&player.Position.Z<FamilyZ-5.2)break;}MigrationChecks.Assert(player.Position.Y>familyFloor+3.35,"Player physically climbs upstairs without teleporting / reached "+familyHome.ToLocal(player.Position));player.Velocity=Vector3.Zero;var ray=PhysicsRayQueryParameters3D.Create(FamilyPoint(0,8,16),FamilyPoint(0,-12,16));ray.Exclude=new(){player.GetRid()};var hit=GetWorld3D().DirectSpaceState.IntersectRay(ray);MigrationChecks.Assert(hit.Count>0&&((Node)hit["collider"].AsGodotObject()).GetParent().Name=="WillowPorchAccess"&&((Vector3)hit["normal"]).Y>.5,"Front access ramp has a walkable collision surface");player.Position=FamilyPoint(-3,3.55f,-3);MigrationChecks.Assert(FamilyOperation()=="","Upstairs cannot activate the basement through the floor");player.Position=FamilyPoint(-4,.1f,-5.4f);MigrationChecks.Assert(FamilyOperation()=="photo","Relocated family portrait remains accessible");GD.Print("PASS / Victorian house staircase collision, accessible upper floor and relocated story portrait");}
